import React from 'react';

type Props = { title: string; description?: string };

export default function PlaceholderPage({ title, description }: Props) {
  return (
    <div style={{ minHeight: '100%', backgroundColor: '#F9FAFB' }}>
      <div style={{ padding: '2rem 2.5rem' }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#2c313c', margin: 0 }}>
          {title}
        </h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '8px 0 0', maxWidth: 520 }}>
          {description ?? 'This section is ready to be connected to your RedFlagAlert workflow or embed.'}
        </p>
      </div>
    </div>
  );
}
